"""Generate reviewable C driver stubs from a snapshot + findings."""

from __future__ import annotations

from bringupbench.models import BoardSnapshot, BusKind, Finding


I2C_STUB = """\
/* Generated by Bringup Bench — review before flash.
 * Board: {board}  MCU: {mcu}
 * Device: {name} on {instance}  7-bit addr 0x{addr:02X}
 */
#include "bringup_hal.h"

#define {NAME}_ADDR  (0x{addr:02X}u)

int {name}_whoami(uint8_t *id)
{{
    uint8_t reg = 0x7E;
    if (i2c_write({instance_l}, {NAME}_ADDR, &reg, 1) != 0)
        return -1;
    return i2c_read({instance_l}, {NAME}_ADDR, id, 1);
}}
"""

SPI_STUB = """\
/* Generated by Bringup Bench — SPI mode {mode} (CPOL/CPHA).
 * Device: {name} on {instance}
 */
#include "bringup_hal.h"

int {name}_whoami(uint8_t *id)
{{
    uint8_t tx[2] = {{ 0x8F, 0x00 }};
    uint8_t rx[2] = {{ 0 }};
    spi_set_mode({instance_l}, {mode});
    if (spi_xfer({instance_l}, tx, rx, 2) != 0)
        return -1;
    *id = rx[1];
    return 0;
}}
"""

UART_STUB = """\
/* Console / fixture UART at {baud} 8N1 on {instance} */
#include "bringup_hal.h"

void console_init(void)
{{
    usart_set_baud({instance_l}, {baud});
    usart_set_format({instance_l}, 8, USART_PARITY_NONE, 1);
}}
"""

CLOCK_STUB = """\
/* Enable gated clocks before first bus transaction */
#include "bringup_hal.h"

void board_clocks_enable(void)
{{
    rcc_enable("I2C1");
    rcc_enable("SPI1");
    rcc_enable("USART2");
}}
"""


def generate_stubs(snapshot: BoardSnapshot, findings: list[Finding] | None = None) -> dict[str, str]:
    findings = findings if findings is not None else snapshot.findings
    files: dict[str, str] = {"board_clocks.c": CLOCK_STUB}

    for p in snapshot.peripherals:
        ident = p.name.replace("-", "_")
        if p.kind == BusKind.I2C:
            addr = int(p.hardware_config.get("addr", p.address or 0x44))
            files[f"{ident}.c"] = I2C_STUB.format(
                board=snapshot.board,
                mcu=snapshot.mcu,
                name=ident,
                NAME=ident.upper(),
                instance=p.instance,
                instance_l=p.instance.lower(),
                addr=addr,
            )
        elif p.kind == BusKind.SPI:
            mode = int(p.hardware_config.get("mode", 0))
            files[f"{ident}.c"] = SPI_STUB.format(
                name=ident,
                instance=p.instance,
                instance_l=p.instance.lower(),
                mode=mode,
            )
        elif p.kind == BusKind.UART:
            baud = int(p.hardware_config.get("baud", 115200))
            files[f"{ident}.c"] = UART_STUB.format(
                baud=baud,
                instance=p.instance,
                instance_l=p.instance.lower(),
            )

    notes = ["/* Bringup Bench findings to close before merge:", ""]
    for f in findings:
        notes.append(f" * [{f.severity}] {f.code} {f.resource}: {f.title}")
        if f.suggested_action:
            notes.append(f" *    -> {f.suggested_action}")
    notes.append(" */\n")
    files["FINDINGS.h"] = "\n".join(notes)
    return files
